def canonical(smiles: str) -> str:
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        raise ValueError(f"invalid SMILES: {smiles}")
    return Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True)


def methylated_precursor(product_smiles: str, prefer_acid: bool = False) -> str:
    mol = Chem.MolFromSmiles(product_smiles)
    if mol is None:
        raise ValueError(f"invalid product: {product_smiles}")

    acid_matches = mol.GetSubstructMatches(Chem.MolFromSmarts("C(=O)[OX1H0,OX2H1]"))
    candidates: list[int] = []
    if prefer_acid and acid_matches:
        # Match tuple is carbonyl C, carbonyl O, acid O.
        candidates.append(acid_matches[0][2])
    for atom in mol.GetAtoms():
        if atom.GetTotalNumHs() > 0 and atom.GetSymbol() in {"N", "O"}:
            candidates.append(atom.GetIdx())
    for atom in mol.GetAtoms():
        if atom.GetTotalNumHs() > 0 and atom.GetSymbol() == "C":
            candidates.append(atom.GetIdx())

    for atom_idx in candidates:
        rw = Chem.RWMol(mol)
        carbon_idx = rw.AddAtom(Chem.Atom("C"))
        rw.AddBond(atom_idx, carbon_idx, Chem.BondType.SINGLE)
        precursor = rw.GetMol()
        try:
            Chem.SanitizeMol(precursor)
        except Exception:
            continue
        precursor_smiles = Chem.MolToSmiles(precursor, canonical=True, isomericSmiles=True)
        if precursor_smiles != canonical(product_smiles):
            return precursor_smiles
    raise ValueError(f"could not create precursor for {product_smiles}")


def atom_inventory_route(product_smiles: str) -> str:
    mol = Chem.MolFromSmiles(product_smiles)
    if mol is None:
        raise ValueError(f"invalid product: {product_smiles}")
    counts = Counter(atom.GetSymbol() for atom in mol.GetAtoms())
    pieces = []
    for element in sorted(counts):
        pieces.extend([element] * counts[element])
    return ".".join(pieces) + ">>" + canonical(product_smiles)


def route_for(product_smiles: str, strategy: str) -> str:
    product = canonical(product_smiles)
    if strategy == "auto_methyl_ester":
        return methylated_precursor(product, prefer_acid=True) + ">>" + product
    if strategy == "auto_methyl_precursor":
        return methylated_precursor(product, prefer_acid=False) + ">>" + product
    if strategy == "tyk2_vzj_snar":
        reactants = [
            "CNC(=O)c1c(Cl)c(nn1NC(=O)C2CC2)Cl",
            "Nc1cccc(c1OC)c2ncccn2",
        ]
        return ".".join(canonical(smi) for smi in reactants) + ">>" + product
    if strategy == "gpr119_i7j_snar":
        reactants = [
            "CC(C)OC(=O)N1CCC(O)CC1",
            "Clc1c2cnn(c2ncn1)c3ccc(cc3F)S(=O)(=O)C",
        ]
        return ".".join(canonical(smi) for smi in reactants) + ">>" + product
    if strategy == "atom_inventory":
        return atom_inventory_route(product)
    raise ValueError(f"unknown route strategy: {strategy}")


def make_archive(rows_by_member: dict[str, list[dict[str, str]]], out: Path, log_text: str) -> None:
    old_rows = os.environ.get("TARGETMOL_ROWS_PER_TARGET")
    os.environ["TARGETMOL_ROWS_PER_TARGET"] = str(max(len(rows) for rows in rows_by_member.values()))
    try:
        write_submission(out, rows_by_member, log_text)
    finally:
        if old_rows is None:
            os.environ.pop("TARGETMOL_ROWS_PER_TARGET", None)
        else:
            os.environ["TARGETMOL_ROWS_PER_TARGET"] = old_rows


def build_panel() -> tuple[dict[str, list[dict[str, str]]], dict[str, list[dict[str, str]]]]:
    tables: dict[str, list[dict[str, str]]] = {}
    metadata: dict[str, list[dict[str, str]]] = {}
    for member, entries in TARGETS.items():
        tables[member] = []
        metadata[member] = []
        for entry in entries:
            product = canonical(entry["smiles"])
            route = route_for(product, entry["route"])
            tables[member].append({"mol_smiles": product, "route": route})
            metadata[member].append({**entry, "canonical_smiles": product, "route": route})
    return tables, metadata


def main() -> int:
    out_dir = Path("experiments/candidates")
    out_dir.mkdir(parents=True, exist_ok=True)
    tables, metadata = build_panel()
    make_archive(
        tables,
        out_dir / "panel.zip",
        "Target-specific panel: MCL1, TYK2 JH2, and GPR119 candidates from RCSB/probe/stage-B evidence.\n",
    )
    (out_dir / "panel_metadata.json").write_text(json.dumps(metadata, indent=2, sort_keys=True) + "\n")
    print(out_dir / "panel.zip")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

